  const vE=Math.exp(-Math.min(cX-sx*0.12,1-(cX-sx*0.12))*Math.min(cY-sy*0.12,1-(cY-sy*0.12))*80)*0.3;
  const reaction=Math.tanh((act-inh*0.65+bg*0.3+spiral+harm*0.4)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
