  const pal=[[4,8,42],[8,35,78],[14,78,110],[20,132,138],[50,178,148],[145,212,125],[225,212,75],[242,158,58],[232,98,68],[182,48,82],[98,22,68],[48,12,55],[4,8,42]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const r=pal[i][0]+(pal[i+1][0]-pal[i][0])*sf;
  const g=pal[i][1]+(pal[i+1][1]-pal[i][1])*sf;
  const b=pal[i][2]+(pal[i+1][2]-pal[i][2])*sf;
